// Decide whether this week is worth a MODEL CALL, and build the prompt if so.
//
// Cost-awareness: most weeks nothing we depend on moves a decision. Routing a
// prompt anyway would spend capacity to be told "no change" — so the IF node
// downstream skips the agent entirely on a quiet week. The lane still posts,
// because "we checked and it was quiet" is a coverage signal worth seeing;
// silence would be indistinguishable from the lane being broken.
const d = $input.first().json || {};
const NL = String.fromCharCode(10);

// A failed fetch must never read as a clean bill of health.
const partial = d.checked_all_sources === false;
const drift = d.version_drift || [];
const notable = (d.items || []).filter(i => i.notable);

if (d.releases === undefined) {
  return [{ json: { needsAgent: false, severity: 'warn',
    title: 'Research lane: the lane call itself failed',
    message: ['Response had no shape we recognise.',
              JSON.stringify(d).slice(0, 400)].join(NL),
    source: 'research-watch' } }];
}

// Facts the agent reasons over. Each item already carries WHICH RECORDED
// DECISION it could move — the runner is firewalled and cannot look anything
// up, so everything it needs has to travel in the prompt.
const facts = notable.map(i =>
  `- ${i.repo} ${i.tag} (${i.published}) [${i.running ? 'WE RUN THIS' : 'watched candidate — NOT deployed'}]` + NL +
  `  signals=[${i.signals.join(', ')}]` + NL +
  `  we depend on it because: ${i.why}` + NL +
  `  it could move: ${i.decision}` + NL +
  `  release says: ${(i.excerpt || '').slice(0, 300)}`
).join(NL);

// The OUTCOME, phrased as a headline — "n8n is 2 minor versions behind"
// rather than "the watch ran and found 2 things". Rule 1 of the message
// contract: a title that only names the job makes the reader open the body
// to learn whether anything happened.
const driftLead = drift.length
  ? `${drift[0].repo.split('/').pop()} is ${drift[0].behind.replace('0 major, ', '')} version(s) behind` +
    ` (${drift[0].pinned} → ${drift[0].latest})` +
    (drift.length > 1 ? ` +${drift.length - 1} more` : '')
  : '';

const driftText = drift.map(r =>
  `- ${r.repo}: we PIN ${r.pinned}, released ${r.latest} on ${r.published} (${r.behind} behind)`
).join(NL);

const prompt = [
  'You advise the maintainers of an AI agent control plane. Below is a watch',
  'report generated by a tool, not a human. It covers two different things and',
  'the difference matters: components WE RUN, where a release is an operational',
  'event, and WATCHED CANDIDATES we have deliberately NOT deployed, where a',
  'release is at most an input to a future decision. Each entry is labelled and',
  'names the recorded decision it might move.',
  '',
  'BE SKEPTICAL. Most releases move no decision. Saying "nothing here warrants a',
  'change" is a correct and valuable answer; inventing work is not. Do not',
  'recommend adopting anything merely because it is new.',
  '',
  'RELEASES CARRYING A DECISION-MOVING SIGNAL:',
  facts || '(none)',
  '',
  'VERSION DRIFT (what we pin vs what shipped):',
  driftText || '(none)',
  '',
  partial ? 'WARNING: some sources were UNREACHABLE, so this is a PARTIAL view: ' +
            (d.unreachable || []).join('; ') : '',
  '',
  'Answer in at most 5 short bullets. For each, state: the decision affected, whether',
  'it actually moves, and the concrete next action (or "no action"). Name any claim you',
  'could not verify from the text above rather than filling the gap.',
].join(NL);

const severity = drift.length || partial ? 'warn' : (notable.length ? 'info' : 'info');
return [{ json: {
  needsAgent: notable.length > 0 || drift.length > 0,
  severity, prompt,
  releases: d.releases, notableCount: notable.length,
  driftCount: drift.length, partial,
  unreachable: (d.unreachable || []).join('; '),
  driftText, driftLead, source: 'research-watch',
} }];

// Reshape the router's decision + the agent's advice into a notification.
//
// The router's reply is the AUTHORITY on what happened: if it blocked the call
// (circuit breaker, mode, guardrail) that is the story, not a missing answer.
const r = $input.first().json || {};
const t = $('Triage findings').first().json || {};
const NL = String.fromCharCode(10);

if (r.blocked) {
  return [{ json: {
    severity: 'warn',
    title: 'Research lane: the router BLOCKED the analysis',
    message: ['blocked: ' + r.blocked, r.message || '',
              'The findings below were still collected:', t.driftText || '(no drift)'].join(NL),
    source: 'research-watch',
  } }];
}

// claude-runner returns { result: { result: "<text>" } }; older shapes nest
// differently. Pull the text without assuming one, and say so if we cannot.
const inner = r.result || {};
const advice = (typeof inner === 'string') ? inner
             : (typeof inner.result === 'string') ? inner.result
             : (inner.result && inner.result.result) || '';
const dec = r.decision || {};
const usage = r.usage || {};

// Outcome, not event. No severity emoji here — Notify prepends one, and two
// would just be noise.
const head = t.driftLead
  ? t.driftLead
  : (t.notableCount
      ? `${t.notableCount} release(s) could move a recorded decision`
      : 'Nothing moved a recorded decision');

const body = [
  t.driftText || '',
  t.partial ? 'PARTIAL VIEW — unreachable: ' + t.unreachable : '',
  '',
  advice ? advice.slice(0, 2500)
         : 'The agent returned no text. This is a lane fault, not a quiet week.',
  '',
  `_tier ${dec.tier || '?'} · ${dec.model || '?'}${dec.clamped ? ' (clamped by cost ceiling)' : ''}` +
  ` · notional $${(usage.notionalCostUsd || 0).toFixed(4)}_`,
].filter(Boolean).join(NL);

// Contract fields (notification-taxonomy.md "The message contract"):
// an explicit action line, the one number that matters, and a deep link to
// THIS execution. $execution.id here is the lane's own run, which is what a
// reader needs — the Notify sub-workflow has its own id and cannot derive it.
const base = ($env.N8N_BASE_URL || 'http://localhost:5678').replace(/\/+$/, '');
const action = t.driftCount
  ? 'Act by the next pin review (2026-08-24) — queued in context/image-policy.json'
  : (t.notableCount ? 'Decide this week' : 'No action');
return [{ json: {
  severity: t.severity || 'info',
  title: head,
  action,
  metric: `${t.notableCount} of ${t.releases} release(s) carry a signal` +
          (t.driftCount ? `, ${t.driftCount} pin behind` : ''),
  runUrl: `${base}/workflow/${$workflow.id}/executions/${$execution.id}`,
  message: body,
  source: 'research-watch',
} }];

// A quiet week still posts. Coverage-first (notification-taxonomy.md): a lane
// that only speaks when it finds something is indistinguishable from a lane that
// stopped running, and the second failure is the dangerous one.
const t = $input.first().json || {};
const NL = String.fromCharCode(10);
if (t.severity === 'warn' && t.title) return [{ json: t }];   // lane fault, pass through
return [{ json: {
  severity: t.partial ? 'warn' : 'info',
  title: 'Nothing moved a recorded decision',
  action: 'No action',
  metric: `0 of ${t.releases} release(s) carry a signal`,
  message: [
    `Checked 6 sources; ${t.releases} release(s) in the window, none carrying a`,
    'decision-moving signal, and no version drift against context/image-policy.json.',
    t.partial ? 'PARTIAL VIEW — these sources were NOT checked: ' + t.unreachable : '',
    '_No model call was made — nothing to reason about._',
  ].filter(Boolean).join(NL),
  source: 'research-watch',
} }];
